:19rpx;border:1rpx solid #ddd7cf;border-radius:12rpx;background:#fff;color:#5f5a52;font-size:20rpx}.error{border-color:#e4c3bc;background:#fbf1ef;color:#955446;font-size:20rpx}@media(min-width:780px){.page{padding-bottom:40px}}
